def solve(nums: list[int], target: int) -> list[int]:
    # Return the 0-based indices [i, j] (i < j) of the two elements of nums
    # whose sum equals target. Exactly one valid answer exists.
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

