package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
	"syscall"
)

// Keep "sort" imported so user solutions may use it; the reference template
// below relies on it. Without a use here Go would reject solutions that don't.
var _ = sort.Ints

{{.}}

func main() {
	// Move bash-supplied fd 3 to a private fd and close fd 3 so user code
	// can't poke at it. The duplicate is used to deliver the answer below.
	dupFd, _ := syscall.Dup(3)
	_ = syscall.Close(3)
	answer := os.NewFile(uintptr(dupFd), "answer")

	// stdin holds one test case: "n x" then the n weights. ScanWords tokenizes
	// across the line break; the buffer is enlarged for the 2e5-weight cases.
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1024*1024), 64*1024*1024)
	sc.Split(bufio.ScanWords)
	readInt := func() int64 {
		sc.Scan()
		v, _ := strconv.ParseInt(sc.Text(), 10, 64)
		return v
	}

	n := readInt()
	x := readInt()
	weights := make([]int64, n)
	for i := int64(0); i < n; i++ {
		weights[i] = readInt()
	}

	result := solve(x, weights)

	_, _ = answer.WriteString(strconv.FormatInt(result, 10))
	_ = answer.Close()
}

