// weights[i] is the weight of child i. A gondola holds one or two children and
// its total weight may not exceed x. Return the minimum number of gondolas.
//
// Two-pointer greedy: sort the children, then repeatedly try to pair the
// lightest remaining child with the heaviest. If they fit together they share a
// gondola; otherwise the heaviest rides alone. Either way the heaviest is now
// seated, so advance from the top.
func solve(x int64, weights []int64) int64 {
	sort.Slice(weights, func(a, b int) bool { return weights[a] < weights[b] })
	i, j := 0, len(weights)-1
	var gondolas int64
	for i <= j {
		if i == j {
			gondolas++
			break
		}
		if weights[i]+weights[j] <= x {
			i++
		}
		j--
		gondolas++
	}
	return gondolas
}
